"""Owner Mode authentication: WebAuthn / passkey plus server-side sessions.

This replaces the previous shared-token owner scheme. Design points:

* The private key never leaves the authenticator (e.g. Windows Hello). The server
  stores only the non-secret *public* credential record and verifies signatures
  with the maintained ``webauthn`` (py_webauthn) library, never with custom
  cryptography.
* User verification is **required**, not merely user presence.
* Challenges are cryptographically random (generated by py_webauthn), single-use,
  age-limited and bounded in number.
* Authentication is proven by the assertion signature over the challenge, never
  by knowledge of a public key or credential ID.
* The relying-party ID and accepted origins come only from trusted configuration;
  a passkey registered for one RP ID is not valid for another.
* A successful assertion issues an opaque, server-side, short-lived owner
  session. A frontend boolean is never proof of authentication.

The stores are in-memory and therefore concurrency-safe but process-local: a
backend restart invalidates every session. A distributed deployment would need
shared session storage; this single-process deployment does not.
"""

from __future__ import annotations

import hashlib
import json
import secrets
import threading
import time
from collections import deque
from dataclasses import dataclass
from datetime import UTC, datetime
from typing import Any

import webauthn
from webauthn.helpers import bytes_to_base64url
from webauthn.helpers.structs import (
    AuthenticatorSelectionCriteria,
    AuthenticatorTransport,
    PublicKeyCredentialDescriptor,
    ResidentKeyRequirement,
    UserVerificationRequirement,
)

from rag_workbench.config import Settings
from rag_workbench.domain.errors import (
    AuthenticationThrottledError,
    BootstrapDisabledError,
    WebAuthnNotConfiguredError,
    WebAuthnVerificationError,
)

_KIND_REGISTRATION = "registration"
_KIND_AUTHENTICATION = "authentication"


def _iso(timestamp: float) -> str:
    return datetime.fromtimestamp(timestamp, tz=UTC).isoformat()


@dataclass(frozen=True)
class StoredCredential:
    """A non-secret, persisted owner passkey record."""

    credential_id: str
    public_key: str
    sign_count: int = 0
    label: str | None = None
    transports: tuple[str, ...] = ()
    aaguid: str | None = None
    device_type: str | None = None
    backed_up: bool | None = None
    created_at: str | None = None

    def public_dict(self) -> dict[str, Any]:
        return {
            "credential_id": self.credential_id,
            "public_key": self.public_key,
            "sign_count": self.sign_count,
            "label": self.label,
            "transports": list(self.transports),
            "aaguid": self.aaguid,
            "device_type": self.device_type,
            "backed_up": self.backed_up,
            "created_at": self.created_at,
        }


def _opt_str(value: object) -> str | None:
    return value if isinstance(value, str) else None


def parse_credentials(raw: str) -> list[StoredCredential]:
    """Parse the configured public-credential JSON, failing closed on garbage.

    A malformed store yields no credentials (Owner Mode stays locked) rather than
    an error that could be mistaken for availability.
    """

    try:
        data = json.loads(raw or "[]")
    except (json.JSONDecodeError, TypeError):
        return []
    if not isinstance(data, list):
        return []
    credentials: list[StoredCredential] = []
    for item in data:
        if not isinstance(item, dict):
            continue
        credential_id = item.get("credential_id")
        public_key = item.get("public_key")
        if not isinstance(credential_id, str) or not isinstance(public_key, str):
            continue
        if not credential_id or not public_key:
            continue
        transports = item.get("transports")
        credentials.append(
            StoredCredential(
                credential_id=credential_id,
                public_key=public_key,
                sign_count=int(item.get("sign_count") or 0),
                label=_opt_str(item.get("label")),
                transports=tuple(t for t in transports if isinstance(t, str))
                if isinstance(transports, list)
                else (),
                aaguid=_opt_str(item.get("aaguid")),
                device_type=_opt_str(item.get("device_type")),
                backed_up=item.get("backed_up")
                if isinstance(item.get("backed_up"), bool)
                else None,
                created_at=_opt_str(item.get("created_at")),
            )
        )
    return credentials


@dataclass
class _PendingChallenge:
    kind: str
    challenge: bytes
    created_at: float


class ChallengeStore:
    """Bounded, single-use, age-limited WebAuthn challenges."""

    def __init__(self, *, ttl_s: float, max_pending: int) -> None:
        self._ttl_s = ttl_s
        self._max_pending = max_pending
        self._items: dict[str, _PendingChallenge] = {}
        self._lock = threading.Lock()

    def create(self, kind: str, challenge: bytes) -> str:
        now = time.monotonic()
        handle = secrets.token_urlsafe(24)
        with self._lock:
            self._purge(now)
            if len(self._items) >= self._max_pending:
                oldest = min(self._items, key=lambda k: self._items[k].created_at)
                del self._items[oldest]
            self._items[handle] = _PendingChallenge(kind, challenge, now)
        return handle

    def consume(self, handle: str, kind: str) -> bytes | None:
        now = time.monotonic()
        with self._lock:
            self._purge(now)
            item = self._items.pop(handle, None)
        if item is None or item.kind != kind:
            return None
        return item.challenge

    def _purge(self, now: float) -> None:
        expired = [k for k, v in self._items.items() if now - v.created_at > self._ttl_s]
        for key in expired:
            del self._items[key]


@dataclass(frozen=True)
class OwnerSession:
    token: str
    credential_id: str
    label: str | None
    issued_at_iso: str
    idle_expires_at_iso: str
    absolute_expires_at_iso: str
    _idle_expires_at: float
    _absolute_expires_at: float

    def public_dict(self) -> dict[str, Any]:
        return {
            "credential_label": self.label,
            "issued_at": self.issued_at_iso,
            "expires_at": self.idle_expires_at_iso,
            "absolute_expires_at": self.absolute_expires_at_iso,
        }


class OwnerSessionStore:
    """In-memory, thread-safe owner sessions with idle and absolute lifetimes."""

    def __init__(self, *, idle_ttl_s: float, absolute_ttl_s: float, max_sessions: int) -> None:
        self._idle_ttl_s = idle_ttl_s
        self._absolute_ttl_s = absolute_ttl_s
        self._max_sessions = max_sessions
        self._sessions: dict[str, OwnerSession] = {}
        self._lock = threading.Lock()

    def issue(self, *, credential_id: str, label: str | None) -> OwnerSession:
        now = time.monotonic()
        wall = time.time()
        session = OwnerSession(
            token=secrets.token_urlsafe(48),
            credential_id=credential_id,
            label=label,
            issued_at_iso=_iso(wall),
            idle_expires_at_iso=_iso(wall + self._idle_ttl_s),
            absolute_expires_at_iso=_iso(wall + self._absolute_ttl_s),
            _idle_expires_at=now + self._idle_ttl_s,
            _absolute_expires_at=now + self._absolute_ttl_s,
        )
        with self._lock:
            self._purge(now)
            if len(self._sessions) >= self._max_sessions:
                oldest = min(self._sessions, key=lambda k: self._sessions[k]._idle_expires_at)
                del self._sessions[oldest]
            self._sessions[session.token] = session
        return session

    def validate(self, token: str) -> OwnerSession | None:
        if not token:
            return None
        now = time.monotonic()
        with self._lock:
            self._purge(now)
            session = self._sessions.get(token)
            if session is None:
                return None
            # Sliding idle window, bounded by the absolute deadline.
            refreshed = OwnerSession(
                token=session.token,
                credential_id=session.credential_id,
                label=session.label,
                issued_at_iso=session.issued_at_iso,
                idle_expires_at_iso=_iso(time.time() + self._idle_ttl_s),
                absolute_expires_at_iso=session.absolute_expires_at_iso,
                _idle_expires_at=min(now + self._idle_ttl_s, session._absolute_expires_at),
                _absolute_expires_at=session._absolute_expires_at,
            )
            self._sessions[token] = refreshed
            return refreshed

    def revoke(self, token: str) -> bool:
        with self._lock:
            return self._sessions.pop(token, None) is not None

    def revoke_all(self) -> int:
        with self._lock:
            count = len(self._sessions)
            self._sessions.clear()
        return count

    def _purge(self, now: float) -> None:
        expired = [
            k
            for k, v in self._sessions.items()
            if now >= v._idle_expires_at or now >= v._absolute_expires_at
        ]
        for key in expired:
            del self._sessions[key]


class AttemptLimiter:
    """A simple sliding-window attempt limiter (process-local, thread-safe)."""

    def __init__(self, *, max_attempts: int, window_s: float) -> None:
        self._max_attempts = max_attempts
        self._window_s = window_s
        self._events: deque[float] = deque()
        self._lock = threading.Lock()

    def allow(self) -> bool:
        now = time.monotonic()
        with self._lock:
            while self._events and now - self._events[0] > self._window_s:
                self._events.popleft()
            if len(self._events) >= self._max_attempts:
                return False
            self._events.append(now)
            return True


class OwnerAuthService:
    """WebAuthn ceremonies and owner sessions, configured from trusted settings."""

    def __init__(self, settings: Settings) -> None:
        self._settings = settings
        self._rp_id = settings.webauthn_rp_id.strip()
        self._rp_name = settings.webauthn_rp_name
        self._origins = tuple(o.strip() for o in settings.webauthn_origins if o.strip())
        self._user_id = hashlib.sha256(
            settings.webauthn_owner_user_id.encode("utf-8")
        ).digest()[:32]
        self._credentials = parse_credentials(settings.webauthn_credentials)
        self._challenges = ChallengeStore(
            ttl_s=settings.webauthn_challenge_ttl_s,
            max_pending=settings.webauthn_max_pending_challenges,
        )
        self._sessions = OwnerSessionStore(
            idle_ttl_s=settings.webauthn_session_idle_ttl_s,
            absolute_ttl_s=settings.webauthn_session_absolute_ttl_s,
            max_sessions=settings.webauthn_max_sessions,
        )
        self._registration_limiter = AttemptLimiter(
            max_attempts=settings.webauthn_registration_max_attempts,
            window_s=settings.webauthn_rate_window_s,
        )
        self._authentication_limiter = AttemptLimiter(
            max_attempts=settings.webauthn_authentication_max_attempts,
            window_s=settings.webauthn_rate_window_s,
        )
        self._sign_counts: dict[str, int] = {}
        self._sign_lock = threading.Lock()

    # -- capability reporting ------------------------------------------------

    @property
    def available(self) -> bool:
        """Whether an RP ID and accepted origin are configured."""

        return bool(self._rp_id and self._origins)

    @property
    def credential_count(self) -> int:
        return len(self._credentials)

    @property
    def registration_enabled(self) -> bool:
        return self.available and self._settings.webauthn_bootstrap_ready

    @property
    def rp_id(self) -> str:
        return self._rp_id

    @property
    def origins(self) -> tuple[str, ...]:
        return self._origins

    def public_summary(self) -> dict[str, Any]:
        """Non-sensitive capability facts for ``/v1/config`` (no visitor status)."""

        return {
            "authentication_available": self.available,
            "credential_configured": self.credential_count > 0,
            "registration_enabled": self.registration_enabled,
            "rp_id": self._rp_id,
            "origins": list(self._origins),
        }

    # -- registration (one-time bootstrap) -----------------------------------

    def registration_options(self) -> tuple[str, str]:
        if not self.available:
            raise WebAuthnNotConfiguredError(
                "owner passkey authentication is not configured on this deployment"
            )
        if not self.registration_enabled:
            raise BootstrapDisabledError(
                "owner passkey bootstrap enrollment is disabled or has no token"
            )
        if not self._registration_limiter.allow():
            raise AuthenticationThrottledError(
                "too many registration attempts; try again later"
            )
        options = webauthn.generate_registration_options(
            rp_id=self._rp_id,
            rp_name=self._rp_name,
            user_name="owner",
            user_id=self._user_id,
            user_display_name="RAG Workbench owner",
            authenticator_selection=AuthenticatorSelectionCriteria(
                user_verification=UserVerificationRequirement.REQUIRED,
                resident_key=ResidentKeyRequirement.PREFERRED,
            ),
            exclude_credentials=[
                PublicKeyCredentialDescriptor(
                    id=webauthn.base64url_to_bytes(c.credential_id)
                )
                for c in self._credentials
            ],
        )
        handle = self._challenges.create(_KIND_REGISTRATION, options.challenge)
        return handle, webauthn.options_to_json(options)

    def verify_registration(
        self, *, handle: str, credential: dict[str, Any], label: str | None
    ) -> dict[str, Any]:
        if not self.registration_enabled:
            raise BootstrapDisabledError(
                "owner passkey bootstrap enrollment is disabled or has no token"
            )
        challenge = self._challenges.consume(handle, _KIND_REGISTRATION)
        if challenge is None:
            raise WebAuthnVerificationError(
                "registration challenge is missing, expired or already used"
            )
        try:
            verified = webauthn.verify_registration_response(
                credential=credential,
                expected_challenge=challenge,
                expected_rp_id=self._rp_id,
                expected_origin=list(self._origins),
                require_user_verification=True,
            )
        except Exception as exc:  # noqa: BLE001 - normalise any library failure
            raise WebAuthnVerificationError(
                "registration response could not be verified"
            ) from exc
        transports = self._transports_from(credential)
        record = StoredCredential(
            credential_id=bytes_to_base64url(verified.credential_id),
            public_key=bytes_to_base64url(verified.credential_public_key),
            sign_count=verified.sign_count,
            label=label or "owner passkey",
            transports=transports,
            aaguid=str(verified.aaguid),
            device_type=getattr(verified.credential_device_type, "value", None),
            backed_up=verified.credential_backed_up,
            created_at=datetime.now(tz=UTC).isoformat(),
        )
        return record.public_dict()

    # -- authentication ------------------------------------------------------

    def authentication_options(self) -> tuple[str, str]:
        if not self.available:
            raise WebAuthnNotConfiguredError(
                "owner passkey authentication is not configured on this deployment"
            )
        if not self._credentials:
            raise WebAuthnNotConfiguredError("no owner passkey is configured")
        if not self._authentication_limiter.allow():
            raise AuthenticationThrottledError(
                "too many authentication attempts; try again later"
            )
        options = webauthn.generate_authentication_options(
            rp_id=self._rp_id,
            allow_credentials=[
                PublicKeyCredentialDescriptor(
                    id=webauthn.base64url_to_bytes(c.credential_id),
                    transports=self._descriptor_transports(c),
                )
                for c in self._credentials
            ],
            user_verification=UserVerificationRequirement.REQUIRED,
        )
        handle = self._challenges.create(_KIND_AUTHENTICATION, options.challenge)
        return handle, webauthn.options_to_json(options)

    def verify_authentication(
        self, *, handle: str, credential: dict[str, Any]
    ) -> dict[str, Any]:
        challenge = self._challenges.consume(handle, _KIND_AUTHENTICATION)
        if challenge is None:
            raise WebAuthnVerificationError(
                "authentication challenge is missing, expired or already used"
            )
        credential_id = credential.get("id") if isinstance(credential, dict) else None
        stored = self._find_credential(credential_id)
        if stored is None:
            raise WebAuthnVerificationError("unknown owner credential")
        try:
            verified = webauthn.verify_authentication_response(
                credential=credential,
                expected_challenge=challenge,
                expected_rp_id=self._rp_id,
                expected_origin=list(self._origins),
                credential_public_key=webauthn.base64url_to_bytes(stored.public_key),
                credential_current_sign_count=self._current_sign_count(stored),
                require_user_verification=True,
            )
        except Exception as exc:  # noqa: BLE001 - normalise any library failure
            raise WebAuthnVerificationError(
                "authentication response could not be verified"
            ) from exc
        self._remember_sign_count(stored.credential_id, verified.new_sign_count)
        session = self._sessions.issue(
            credential_id=stored.credential_id, label=stored.label
        )
        return {"session_token": session.token, **session.public_dict()}

    # -- sessions ------------------------------------------------------------

    def session_info(self, token: str) -> dict[str, Any] | None:
        session = self._sessions.validate(token)
        return session.public_dict() if session is not None else None

    def revoke_session(self, token: str) -> bool:
        return self._sessions.revoke(token)

    # -- internals -----------------------------------------------------------

    def _find_credential(self, credential_id: object) -> StoredCredential | None:
        if not isinstance(credential_id, str):
            return None
        for stored in self._credentials:
            if secrets.compare_digest(stored.credential_id, credential_id):
                return stored
        return None

    def _current_sign_count(self, stored: StoredCredential) -> int:
        with self._sign_lock:
            return self._sign_counts.get(stored.credential_id, stored.sign_count)

    def _remember_sign_count(self, credential_id: str, sign_count: int) -> None:
        with self._sign_lock:
            self._sign_counts[credential_id] = sign_count

    def _descriptor_transports(self, stored: StoredCredential) -> list[Any] | None:
        transports: list[Any] = []
        for value in stored.transports:
            try:
                transports.append(AuthenticatorTransport(value))
            except ValueError:
                continue
        return transports or None

    def _transports_from(self, credential: dict[str, Any]) -> tuple[str, ...]:
        response = credential.get("response") if isinstance(credential, dict) else None
        transports = response.get("transports") if isinstance(response, dict) else None
        if isinstance(transports, list):
            return tuple(t for t in transports if isinstance(t, str))
        return ()


__all__ = [
    "AttemptLimiter",
    "ChallengeStore",
    "OwnerAuthService",
    "OwnerSessionStore",
    "parse_credentials",
]
